"use strict";
var Gordic;
(function (Gordic) {
    var Mdf;
    (function (Mdf) {
        var WebClient;
        (function (WebClient) {
            //var gcontent = Decorators.gcontent;
            //@gcontent
            class GNavrharContent extends GContent {
                constructor() {
                    super(...arguments);
                    this.icon = "gi-pencil"; //ikona do postranniho panelu
                    this.title = "Návrh nového pohledu"; //popisek do tooltipu postranniho panelu
                    this.uid = "GSubcontentNavrh#";
                }
                /** Vola se jednou pri inicializaci (asynchronne) */
                prepareContent(inputParams) {
                    var that = this;
                    const mdfInterface = Gordic.Mdf.Interface;
                    this.hierarchyDataViews = [];
                    this.hierarchies.forEach((h) => {
                        this.CreateDataView(h);
                        //this.hierarchyDataViews.push({ name: h.name, dataView: dataView });
                    });
                    //#region Bars
                    //this.actions = this.actionList; //.addRange({
                    //act2: { caption: "bookmark", captionVisible: "never", icon: "fa-bookmark", run: $.noop },
                    //act3: { caption: "book", captionVisible: "never", icon: "fa-book", run: $.noop },
                    //ok: { caption: GDlg.mbbOk.text, run: () => { if (this.defaultForm?.gform("isValid")) this.close() } },
                    //storno: { caption: GDlg.mbbClose.text, run: () => { this.close() } }
                    //});
                    this.menuBar(this.actions.createBar(["actGenerate*" /*, "actSave*"*/]));
                    //this.commandBar(this.actions.createBar(["ok", "storno"]));
                    //#endregion
                    this.element.empty();
                    //#region Content
                    const formBuilder = new Gordic.Forms.Form("L1M1S1, L-12-12-0, M-12-12-0, S-12-12-0");
                    formBuilder.addRow("Sloupce")
                        .addField("gselectbox", {
                        name: "selectboxColumns",
                        list: true,
                        itemDeletable: false,
                        showSelectButton: false,
                        graphicInput: "hidden",
                        customClass: "js-dropfield ignoreClass",
                        itemTemplate: "<div draggable='true' class='dim{hierarchyIndex} hierarchy' data-index={index} data-hierarchyIndex={hierarchyIndex}>{zkratka}</div>",
                        //data: this.hierarchies.filter((h) => { return h.placement == mdfInterface.HierarchyPlacement.columns; }).sort((a, b) => { return a.index - b.index; }),                                        
                        data: this.setHierarchiesToSelectBox(1 /* mdfInterface.HierarchyPlacement.columns */),
                        validators: [new Gordic.Validators.Required()],
                        change: function (ev, changeObj) {
                            if (changeObj.value != null) {
                                that.currentHierarchy = changeObj.value;
                                that.setDataView(that.currentHierarchy);
                                that.$navrharForm.findFields("selectboxBackground").gselectbox("setValue", null);
                                that.$navrharForm.findFields("selectboxRows").gselectbox("setValue", null);
                            }
                        }
                    })
                        .addRow("Řádky")
                        .addField("gselectbox", {
                        name: "selectboxRows",
                        list: true,
                        itemDeletable: false,
                        showSelectButton: false,
                        graphicInput: "hidden",
                        customClass: "js-dropfield",
                        itemTemplate: "<div draggable='true' class='dim{hierarchyIndex} hierarchy' data-index={index} data-hierarchyIndex={hierarchyIndex}>{zkratka}</div>",
                        //data: this.hierarchies.filter((h) => { return h.placement == mdfInterface.HierarchyPlacement.rows; }).sort((a, b) => { return a.index - b.index; }),  
                        data: this.setHierarchiesToSelectBox(0 /* mdfInterface.HierarchyPlacement.rows */),
                        validators: [new Gordic.Validators.Required()],
                        change: function (ev, changeObj) {
                            if (changeObj.value != null) {
                                that.currentHierarchy = changeObj.value;
                                that.setDataView(that.currentHierarchy);
                                that.$navrharForm.findFields("selectboxColumns").gselectbox("setValue", null);
                                that.$navrharForm.findFields("selectboxBackground").gselectbox("setValue", null);
                            }
                        }
                    })
                        .addRow("Na pozadí")
                        .addField("gselectbox", {
                        name: "selectboxBackground",
                        list: true,
                        itemDeletable: false,
                        showSelectButton: false,
                        graphicInput: "hidden",
                        customClass: "js-dropfield",
                        itemTemplate: "<div draggable='true' class='dim{hierarchyIndex} hierarchy' data-index={index} data-hierarchyIndex={hierarchyIndex}>{zkratka}</div>",
                        //data: this.hierarchies.filter((h) => { return h.placement == mdfInterface.HierarchyPlacement.background; }).sort((a, b) => { return a.index - b.index; }),                                        
                        data: this.setHierarchiesToSelectBox(2 /* mdfInterface.HierarchyPlacement.background */),
                        validators: [new Gordic.Validators.Required()],
                        change: function (ev, changeObj) {
                            if (changeObj.value != null) {
                                that.currentHierarchy = changeObj.value;
                                that.setDataView(that.currentHierarchy);
                                that.$navrharForm.findFields("selectboxColumns").gselectbox("setValue", null);
                                that.$navrharForm.findFields("selectboxRows").gselectbox("setValue", null);
                            }
                        }
                    });
                    this.$navrharForm = $("<div>").appendTo(this.element).gform("createFrom", formBuilder);
                    //this.defaultForm = $.newDiv()
                    //    .appendTo(this.element)
                    //    .gform("createFrom", formBuilder);
                    this.$navrharForm.findFields(".js-dropfield").on("dragstart", (ev) => {
                        this.$draggedDiv = $(ev.target);
                        let hierarchyIndex = this.$draggedDiv.attr("data-hierarchyIndex");
                        this.draggedHierarchy = this.hierarchies[hierarchyIndex];
                        this.$dragSelectBoxFrom = $(ev.target).closest(".gselectbox"); //.gfield("";
                        /*let selectBoxName = this.$dragSelectBoxFrom.attr("data-field");
                        switch (selectBoxName) {
                            case "selectboxColumns":
                                this.draggedHierarchy = this.hierarchiesC[index!];
                                break;
                            case "selectboxRows":
                                this.draggedHierarchy = this.hierarchiesR[index!];
                                break;
                            case "selectboxBackground":
                                this.draggedHierarchy = this.hierarchiesB[index!];
                                break;
                        }*/
                    })
                        .on("dragover", (ev) => {
                        ev.preventDefault();
                    })
                        .on("drop", (ev) => {
                        let $dragSelectBoxTo = $(ev.target).closest(".gselectbox");
                        this.hierarchies.forEach((h) => {
                            if (h.placement === this.draggedHierarchy.placement && h.index > that.draggedHierarchy.index)
                                h.index--;
                        });
                        //smažu hierarchii ze starého seznamu
                        //let selectBoxNameFrom = this.$dragSelectBoxFrom.attr("data-field");
                        /*switch (this.draggedHierarchy.placement) {
                            case mdfInterface.HierarchyPlacement.columns:
                                RemoveDraggedHierarchy(this.hierarchiesC);
                                break;
                            case mdfInterface.HierarchyPlacement.rows:
                                RemoveDraggedHierarchy(this.hierarchiesR);
                                break;
                            case mdfInterface.HierarchyPlacement.background:
                                RemoveDraggedHierarchy(this.hierarchiesB);
                                break;
                        }*/
                        //vložím hierarchii do nového seznamu
                        let selectBoxNameTo = $dragSelectBoxTo.attr("data-field");
                        let oldPlacement = this.draggedHierarchy.placement;
                        switch (selectBoxNameTo) {
                            case "selectboxColumns":
                                //this.draggedHierarchy.index = this.hierarchiesC.length || 0;
                                this.draggedHierarchy.placement = 1 /* mdfInterface.HierarchyPlacement.columns */;
                                //this.hierarchiesC.splice(this.draggedHierarchy.index, 0, this.draggedHierarchy);
                                //$dragSelectBoxTo.gselectbox({ data: this.hierarchiesC });
                                break;
                            case "selectboxRows":
                                //this.draggedHierarchy.index = this.hierarchiesR.length || 0;
                                this.draggedHierarchy.placement = 0 /* mdfInterface.HierarchyPlacement.rows */;
                                //this.hierarchiesR.splice(this.draggedHierarchy.index, 0, this.draggedHierarchy);
                                //$dragSelectBoxTo.gselectbox({ data: this.hierarchiesR });
                                break;
                            case "selectboxBackground":
                                //this.draggedHierarchy.index = this.hierarchiesB.length || 0;
                                this.draggedHierarchy.placement = 2 /* mdfInterface.HierarchyPlacement.background */;
                                //this.hierarchiesB.splice(this.draggedHierarchy.index, 0, this.draggedHierarchy);
                                //$dragSelectBoxTo.gselectbox({ data: this.hierarchiesB});
                                break;
                        }
                        let dataTo = this.hierarchies.filter((h) => { return h.placement == this.draggedHierarchy.placement; });
                        this.draggedHierarchy.index = dataTo.length - 1 || 0;
                        dataTo = dataTo.sort((a, b) => { return a.index - b.index; });
                        $dragSelectBoxTo.gselectbox({ data: dataTo });
                        that.$dragSelectBoxFrom.gselectbox({ data: this.hierarchies.filter((h) => { return h.placement == oldPlacement; }) });
                    });
                    this.$hierarchyGrid = $("<div class='js-mujGrid'>")
                        .css('margin-left', '10px')
                        .appendTo(this.element)
                        .gautofit() // GAutofit - widget, který mění výšku elementu tak, aby vždy vyplnil celou obrazovku. Lze použít místo nastavení height.
                        .ggrid({
                        multi: true,
                        columns: new Gordic.Data.GridFormat()
                            .addStructureColumn({
                            name: "hodnotaNazev",
                            caption: ""
                        })
                    });
                    //#endregion
                    this.beginOperation();
                    setTimeout(() => { this.endOperation(); }, 1000);
                }
                onDeactivate() {
                    console.log("onDeactivate");
                }
                //fce, ktera aktualizuje checkedMembers u hierarchii, ktere jsou nactene do dataview
                AktualizujCheckedMembers() {
                    this.hierarchyDataViews.map((hdw) => {
                        //jestli už je hierarchie nactena do dataview, zjištuji zaskrtnute radky ve stromu, jinak ponecham checkedMembers ty, co jsou v hierarchii (např. načtené z pohledu)
                        if (hdw.nacteno) {
                            let name = hdw.name;
                            let rows = hdw.dataView.getDataRows(true);
                            let checkedRows = rows.filter((row) => { return row.checked === true; });
                            let inputHierarchy = this.hierarchies.filter((h) => h.name === name)[0];
                            inputHierarchy.checkedMembers.splice(0);
                            checkedRows.forEach((row) => {
                                inputHierarchy.checkedMembers.push(row.data.id);
                            });
                        }
                    });
                }
                //fce, která načte hierarchii do stromu
                setDataView(hierarchy) {
                    //není-li zrovna aktuální vybraná hierarchie, není ve stromu, nemusím to řešit
                    if (this.currentHierarchy && hierarchy.name === this.currentHierarchy.name) {
                        const hierarchyDataView = this.hierarchyDataViews.find((dataview) => { return dataview.name == hierarchy.name; });
                        const dataView = hierarchyDataView.dataView;
                        this.$hierarchyGrid.ggrid({ data: dataView });
                        //když už bylo načteno, nenačítám znovu - to bych taky mohl kliknout na ODPA, zaškrtnout něco, pak bych šel na POL, zpátky na ODPA a vše zaškrtlé by se mi přemazalo z inputHierarchy
                        //POZOR, žádoucí je naopak, aby se to vždy načetlo u otevírání nového pohledu (proto dělám nové that.hierarchyDataViews s nacteno=false) a při drillování
                        if (hierarchyDataView.nacteno === false) {
                            const rows = dataView.getDataRows(true, "data");
                            //Zaskrtneme vsechny vybrane prvky
                            rows.forEach((row) => {
                                row.checked = false;
                                hierarchy.checkedMembers.forEach((m) => {
                                    if (row.data.id === m)
                                        row.checked = true;
                                });
                            });
                            const tree = dataView.processors.tree;
                            rows.forEach((row) => {
                                //defaultStateFunction(row);
                                let children = tree.getChildren(row);
                                var breakMe = false;
                                row.structure = $.extend({}, row.structure, { state: "closed" });
                                //kdyz je alespon jeden child zaskrtly, bude vetev rozkliknuta
                                children.forEach((child) => {
                                    if (breakMe == false && child.checked) {
                                        row.structure = $.extend({}, row.structure, { state: "open" });
                                        breakMe = true;
                                    }
                                });
                            });
                            dataView.refresh();
                            hierarchyDataView.nacteno = true;
                        }
                    }
                }
                setNacteno(hierarchy, value) {
                    const hierarchyDataView = this.hierarchyDataViews.find((dataview) => { return dataview.name == hierarchy.name; });
                    hierarchyDataView.nacteno = false; //pri drillovani se bude vzdy prenastavovat dataview podle hierarchie
                }
                CreateDataView(hierarchy) {
                    var filterDto = { hierarchie: hierarchy.name /*, level: 0, parent: "-1"*/ };
                    let treeProcessor = new Gordic.Data.Tree(Gordic.Data.Tree.parentIdOrganizer("idParent"), {
                        //filterKeepStructure: true,
                        defaultState: (row) => {
                            let state = "closed";
                            let children = treeProcessor.getChildren(row);
                            var breakMe = false;
                            //kdyz je alespon jeden child zaskrtly, bude vetev rozkliknuta
                            children.forEach((child) => {
                                if (breakMe == false && child.checked) {
                                    state = "open";
                                    breakMe = true;
                                }
                            });
                            return state;
                        }
                        //dynamicRequest: function (data) {
                        //    return {
                        //        filters: {
                        //            parent: data.id,
                        //            level: data.level + 1,
                        //            hierarchie: hierarchy.name,
                        //            checkedMembers: []
                        //        }
                        //    }
                        //}
                    });
                    let membersDataView = new Gordic.Isl.View(this.isl.PrvekDimenze.list({ filters: filterDto }), {
                        key: "id",
                        processors: {
                            checked: new Gordic.Data.ComputedFieldsProcessor(diff => diff.forEach(row => {
                                //když není nic zaškrtnuto, zaškrtnu všechny v první úrovni (většinou ze začátku)
                                if (!hierarchy.checkedMembers || hierarchy.checkedMembers.length === 0) {
                                    if (row.data.level === 0 && row._autoChecked !== true)
                                        row.checked = row._autoChecked = true;
                                }
                                //když jsou checkedMembers, zaškrtnu je i v dataview
                                else {
                                    var breakMe = false;
                                    hierarchy.checkedMembers.forEach((m, i) => {
                                        if (breakMe === false && m === row.data.id && row._autoChecked !== true) {
                                            row.checked = row._autoChecked = true;
                                            breakMe = true;
                                        }
                                    });
                                }
                            })),
                            tree: treeProcessor,
                        }
                    });
                    this.hierarchyDataViews.push({ name: hierarchy.name, dataView: membersDataView, nacteno: false });
                }
                //funkce pro umístění hierarchií do selectboxů
                setHierarchiesToSelectBox(placement) {
                    return this.hierarchies.filter((h) => { return h.placement == placement; }).sort((a, b) => { return a.index - b.index; });
                }
                ResethierarchyDataViews(hierarchies) {
                    this.hierarchies = hierarchies;
                    //nastavíme nové hierarchyDataViews
                    this.hierarchyDataViews = [];
                    this.hierarchies.forEach((h) => {
                        this.CreateDataView(h);
                    });
                    //nastavíme jednotlivé hierarchie do sloupců, řádků a na pozadí
                    this.$navrharForm.findFields("selectboxColumns").gselectbox("option", { data: this.setHierarchiesToSelectBox(1 /* Interface.HierarchyPlacement.columns */) }).gselectbox("refresh");
                    this.$navrharForm.findFields("selectboxRows").gselectbox("option", { data: this.setHierarchiesToSelectBox(0 /* Interface.HierarchyPlacement.rows */) }).gselectbox("refresh");
                    ;
                    this.$navrharForm.findFields("selectboxBackground").gselectbox("option", { data: this.setHierarchiesToSelectBox(2 /* Interface.HierarchyPlacement.background */) }).gselectbox("refresh");
                    ;
                }
            }
            WebClient.GNavrharContent = GNavrharContent;
        })(WebClient = Mdf.WebClient || (Mdf.WebClient = {}));
    })(Mdf = Gordic.Mdf || (Gordic.Mdf = {}));
})(Gordic || (Gordic = {}));
